async function piAirbnbFillOtp(page, otp) {
  const code = String(otp || '').replace(/\D/g, '');
  if (!code) throw new Error('Empty OTP');
  const single = page.locator('#otp-code-input, input[autocomplete="one-time-code"]').first();
  const boxes = page.locator('input[maxlength="1"]');
  if (await single.count()) {
    await single.click({ timeout: 3000 });
    await single.fill('');
    await single.type(code, { delay: 80 });
  } else if ((await boxes.count()) >= Math.min(4, code.length)) {
    for (let i = 0; i < code.length; i++) {
      const box = boxes.nth(i);
      if (!(await box.count())) break;
      await box.click();
      await box.fill(code[i]);
    }
  } else {
    const otpInput = page.locator('input[name*="code" i], input[inputmode="numeric"], input[type="tel"]').first();
    if (!(await otpInput.count())) throw new Error('OTP input not found on Airbnb page');
    await otpInput.click();
    await otpInput.fill('');
    await otpInput.type(code, { delay: 80 });
  }
  // Airbnb often auto-submits when 6 digits are entered; click Continue only if present
  const cont = page.locator('button:has-text("Continue"), button:has-text("Submit"), button:has-text("Verify"), button[type="submit"]').first();
  if (await cont.count()) await cont.click({ timeout: 2500 }).catch(function () {});
  await page.waitForTimeout(5000);
}

